mapper.select:
/* selectMasterMpStLongTermStckDtList */ SELECT WAREHOUSE_CODE AS TR_CODE , WAREHOUSE_NAME AS TR_NAME , KEP_DEPT AS DEPT_CODE , TEAM_NM AS DEPT_NAME , DECODE(STOCK_GROUP_TYPE, 'A', '불변' , 'B', '가변' ) AS GROUP_TYPE , DECODE(STOCK_MNG, 'F', '불용재고' , 'N', '정상재고' , 'L', '장기재고' ) AS LONG_TERM_TYPE , ITEM_NO AS ITEM_CODE , DESCRIPTION_LOC AS ITEM_NAME , SUM(STOCK_QTY) AS QTY , SUM(STOCK_AMT) AS AMT , IPGO_DATE AS GR_DATE , CHUL_DATE AS IV_DATE , ASB_IPGO_DATE AS GR_DATE_ASMB , ASB_CHUL_DATE AS IV_DATE_ASMB FROM ( SELECT A.WAREHOUSE_CODE , (SELECT REPLACE(TEXT2,'물류센터','') FROM ICOMCOD1 WHERE TYPE = 'W001' AND TEXT1 =A.WAREHOUSE_CODE) AS WAREHOUSE_NAME , A.KEP_DEPT , (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = 'KRKORE0001' AND TYPE = 'C001' AND CODE = A.KEP_DEPT) AS TEAM_NM , A.STOCK_GROUP_TYPE , CASE WHEN STOCK_MNG_CODE = 'L' THEN 'L' WHEN STOCK_MNG_CODE = 'N' THEN 'N' ELSE 'X' END AS STOCK_MNG , A.ITEM_NO , B.DESCRIPTION_LOC , DECODE(A.TYPE,'N',A.STOCK_QTY,A.STOCK_QTY*-1) AS STOCK_QTY , DECODE(A.TYPE,'N',A.STOCK_AMT,A.STOCK_AMT*-1) AS STOCK_AMT , DECODE(LENGTH(A.IPGO_DATE), 8, SUBSTR(A.IPGO_DATE, 1, 4) || '-' || SUBSTR(A.IPGO_DATE, 5, 2) || '-' || SUBSTR(A.IPGO_DATE, 7, 2), A.IPGO_DATE) AS IPGO_DATE , DECODE(LENGTH(A.CHUL_DATE), 8, SUBSTR(A.CHUL_DATE, 1, 4) || '-' || SUBSTR(A.CHUL_DATE, 5, 2) || '-' || SUBSTR(A.CHUL_DATE, 7, 2), CHUL_DATE) AS CHUL_DATE , DECODE(LENGTH(A.ASB_IPGO_DATE), 8, SUBSTR(A.ASB_IPGO_DATE, 1, 4) || '-' || SUBSTR(A.ASB_IPGO_DATE, 5, 2) || '-' || SUBSTR(A.ASB_IPGO_DATE, 7, 2), ASB_IPGO_DATE) AS ASB_IPGO_DATE , DECODE(LENGTH(A.ASB_CHUL_DATE), 8, SUBSTR(A.ASB_CHUL_DATE, 1, 4) || '-' || SUBSTR(A.ASB_CHUL_DATE, 5, 2) || '-' || SUBSTR(A.ASB_CHUL_DATE, 7, 2), ASB_CHUL_DATE) AS ASB_CHUL_DATE FROM KEPSTOCK_MNG A, CMSCATLG B WHERE A.YYYYMM = (SELECT MAX(YYYYMM) FROM KEPSTOCK_MNG) AND A.ITEM_NO = B.CMS_CATLG_ID(+) UNION ALL SELECT A.WAREHOUSE_CODE , (SELECT REPLACE(TEXT2,'물류센터','') FROM ICOMCOD1 WHERE TYPE = 'W001' AND TEXT1 =A.WAREHOUSE_CODE) AS WAREHOUSE_NAME , A.KEP_DEPT , (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = 'KRKORE0001' AND TYPE = 'C001' AND CODE = A.KEP_DEPT) AS TEAM_NM , A.STOCK_GROUP_TYPE , 'F' AS STOCK_MNG , A.ITEM_NO , B.DESCRIPTION_LOC , A.STOCK_QTY , A.STOCK_AMT , DECODE(LENGTH(A.IPGO_DATE), 8, SUBSTR(A.IPGO_DATE, 1, 4) || '-' || SUBSTR(A.IPGO_DATE, 5, 2) || '-' || SUBSTR(A.IPGO_DATE, 7, 2), A.IPGO_DATE) AS IPGO_DATE , DECODE(LENGTH(A.CHUL_DATE), 8, SUBSTR(A.CHUL_DATE, 1, 4) || '-' || SUBSTR(A.CHUL_DATE, 5, 2) || '-' || SUBSTR(A.CHUL_DATE, 7, 2), CHUL_DATE) AS CHUL_DATE , DECODE(LENGTH(A.ASB_IPGO_DATE), 8, SUBSTR(A.ASB_IPGO_DATE, 1, 4) || '-' || SUBSTR(A.ASB_IPGO_DATE, 5, 2) || '-' || SUBSTR(A.ASB_IPGO_DATE, 7, 2), ASB_IPGO_DATE) AS ASB_IPGO_DATE , DECODE(LENGTH(A.ASB_CHUL_DATE), 8, SUBSTR(A.ASB_CHUL_DATE, 1, 4) || '-' || SUBSTR(A.ASB_CHUL_DATE, 5, 2) || '-' || SUBSTR(A.ASB_CHUL_DATE, 7, 2), ASB_CHUL_DATE) AS ASB_CHUL_DATE FROM KEPSTOCK_MNG A, CMSCATLG B WHERE A.YYYYMM = (SELECT MAX(YYYYMM) FROM KEPSTOCK_MNG) AND A.ITEM_NO = B.CMS_CATLG_ID(+) AND A.TYPE = 'F' ) WHERE 1=1
AND WAREHOUSE_CODE = #{st_center_code}
AND STOCK_GROUP_TYPE = #{st_group_type}
AND ITEM_NO = #{st_item_code}
AND KEP_DEPT = #{st_dept}
AND STOCK_MNG = #{st_long_term_type}
GROUP BY WAREHOUSE_CODE , WAREHOUSE_NAME , KEP_DEPT , TEAM_NM , STOCK_GROUP_TYPE , STOCK_MNG , ITEM_NO , DESCRIPTION_LOC , IPGO_DATE , CHUL_DATE , ASB_IPGO_DATE , ASB_CHUL_DATE ORDER BY 1,2,3

/* selectMasterMpStLongTermStckFlowList */ SELECT CASE MNG_CODE WHEN 'L' THEN '장기재고' WHEN 'N' THEN '정상재고' WHEN 'F' THEN '불용재고' ELSE MNG_CODE END AS STCK_TYPE , CASE GROUP_TYPE WHEN 'A' THEN '불변' WHEN 'B' THEN '가변' END AS ITEM_TYPE , ROUND(NVL(M01, 0) / 1000, 0) AS JAN_AMT , ROUND(NVL(M02, 0) / 1000, 0) AS FEB_AMT , ROUND(NVL(M03, 0) / 1000, 0) AS MAR_AMT , ROUND(NVL(M04, 0) / 1000, 0) AS APR_AMT , ROUND(NVL(M05, 0) / 1000, 0) AS MAY_AMT , ROUND(NVL(M06, 0) / 1000, 0) AS JUN_AMT , ROUND(NVL(M07, 0) / 1000, 0) AS JUL_AMT , ROUND(NVL(M08, 0) / 1000, 0) AS AUG_AMT , ROUND(NVL(M09, 0) / 1000, 0) AS SEP_AMT , ROUND(NVL(M10, 0) / 1000, 0) AS OCT_AMT , ROUND(NVL(M11, 0) / 1000, 0) AS NOV_AMT , ROUND(NVL(M12, 0) / 1000, 0) AS DEC_AMT , DECODE(M_TOT, 0, 0, ROUND(M_TOT / ( DECODE(M01, 0, 0, 1) + DECODE(M02, 0, 0, 1) + DECODE(M03, 0, 0, 1) + DECODE(M04, 0, 0, 1) + DECODE(M05, 0, 0, 1) + DECODE(M06, 0, 0, 1) + DECODE(M07, 0, 0, 1) + DECODE(M08, 0, 0, 1) + DECODE(M09, 0, 0, 1) + DECODE(M10, 0, 0, 1) + DECODE(M11, 0, 0, 1) + DECODE(M12, 0, 0, 1) ) / 1000, 0) ) AS AVG_AMT FROM ( SELECT STOCK_MNG_CODE AS MNG_CODE , STOCK_GROUP_TYPE AS GROUP_TYPE , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '01' AND A.TYPE = 'N' THEN STOCK_AMT WHEN SUBSTR(YYYYMM,5,2) = '01' AND A.TYPE = 'F' THEN STOCK_AMT * -1 ELSE 0 END) AS M01 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '02' AND A.TYPE = 'N' THEN STOCK_AMT WHEN SUBSTR(YYYYMM,5,2) = '02' AND A.TYPE = 'F' THEN STOCK_AMT * -1 ELSE 0 END) AS M02 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '03' AND A.TYPE = 'N' THEN STOCK_AMT WHEN SUBSTR(YYYYMM,5,2) = '03' AND A.TYPE = 'F' THEN STOCK_AMT * -1 ELSE 0 END) AS M03 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '04' AND A.TYPE = 'N' THEN STOCK_AMT WHEN SUBSTR(YYYYMM,5,2) = '04' AND A.TYPE = 'F' THEN STOCK_AMT * -1 ELSE 0 END) AS M04 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '05' AND A.TYPE = 'N' THEN STOCK_AMT WHEN SUBSTR(YYYYMM,5,2) = '05' AND A.TYPE = 'F' THEN STOCK_AMT * -1 ELSE 0 END) AS M05 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '06' AND A.TYPE = 'N' THEN STOCK_AMT WHEN SUBSTR(YYYYMM,5,2) = '06' AND A.TYPE = 'F' THEN STOCK_AMT * -1 ELSE 0 END) AS M06 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '07' AND A.TYPE = 'N' THEN STOCK_AMT WHEN SUBSTR(YYYYMM,5,2) = '07' AND A.TYPE = 'F' THEN STOCK_AMT * -1 ELSE 0 END) AS M07 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '08' AND A.TYPE = 'N' THEN STOCK_AMT WHEN SUBSTR(YYYYMM,5,2) = '08' AND A.TYPE = 'F' THEN STOCK_AMT * -1 ELSE 0 END) AS M08 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '09' AND A.TYPE = 'N' THEN STOCK_AMT WHEN SUBSTR(YYYYMM,5,2) = '09' AND A.TYPE = 'F' THEN STOCK_AMT * -1 ELSE 0 END) AS M09 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '10' AND A.TYPE = 'N' THEN STOCK_AMT WHEN SUBSTR(YYYYMM,5,2) = '10' AND A.TYPE = 'F' THEN STOCK_AMT * -1 ELSE 0 END) AS M10 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '11' AND A.TYPE = 'N' THEN STOCK_AMT WHEN SUBSTR(YYYYMM,5,2) = '11' AND A.TYPE = 'F' THEN STOCK_AMT * -1 ELSE 0 END) AS M11 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '12' AND A.TYPE = 'N' THEN STOCK_AMT WHEN SUBSTR(YYYYMM,5,2) = '12' AND A.TYPE = 'F' THEN STOCK_AMT * -1 ELSE 0 END) AS M12 , SUM(CASE WHEN A.TYPE = 'N' THEN STOCK_AMT WHEN A.TYPE = 'F' THEN STOCK_AMT * -1 ELSE 0 END) AS M_TOT FROM KEPSTOCK_MNG A WHERE 1=1 AND YYYYMM BETWEEN #{st_year} || '01' AND #{st_year} || '12'
AND KEP_DEPT = #{st_dept}
GROUP BY STOCK_MNG_CODE , STOCK_GROUP_TYPE UNION ALL SELECT 'F' AS MNG_CODE , '-' AS GROUP_TYPE , SUM(DECODE(SUBSTR(YYYYMM,5,2),'01',STOCK_AMT,0)) AS M01 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'02',STOCK_AMT,0)) AS M02 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'03',STOCK_AMT,0)) AS M03 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'04',STOCK_AMT,0)) AS M04 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'05',STOCK_AMT,0)) AS M05 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'06',STOCK_AMT,0)) AS M06 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'07',STOCK_AMT,0)) AS M07 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'08',STOCK_AMT,0)) AS M08 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'09',STOCK_AMT,0)) AS M09 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'10',STOCK_AMT,0)) AS M10 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'11',STOCK_AMT,0)) AS M11 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'12',STOCK_AMT,0)) AS M12 , SUM(STOCK_AMT) AS M_TOT FROM KEPSTOCK_MNG A WHERE 1=1 AND YYYYMM BETWEEN #{st_year} || '01' AND #{st_year} || '12' AND TYPE = 'F'
AND KEP_DEPT = #{st_dept}
) WHERE 1=1
AND MNG_CODE = #{st_stck_type}
ORDER BY 1 DESC, 2 DESC
